import json

with open('/tmp/gold_data.json') as f:
    data = json.load(f)

price_json = json.dumps(data['price_series'])
hist_centers = json.dumps(data['hist_centers'])
hist_counts = json.dumps(data['hist_counts'])
monthly_avg = json.dumps(data['monthly_avg'])
monthly_heatmap = json.dumps(data['monthly_heatmap'])
annual_returns = json.dumps(data['annual_returns'])
ma_series = json.dumps(data['ma_series'])
vol_annual = json.dumps(data['vol_annual'])

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Gold Price Dynamics: Comprehensive Trend &amp; Volatility Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --gold: #C9A84C;
    --gold-light: #F5D77A;
    --gold-dark: #8B6914;
    --bg: #0F0F14;
    --surface: #18181F;
    --surface2: #22222C;
    --border: #2E2E3C;
    --text: #E8E8EE;
    --text-muted: #8888A0;
    --red: #E05555;
    --green: #4CAF7D;
    --blue: #4A90D9;
    --purple: #9B6BDB;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .header {{
    background: linear-gradient(135deg, #0F0F14 0%, #1A1508 50%, #0F0F14 100%);
    border-bottom: 1px solid var(--gold-dark);
    padding: 3rem 2rem 2rem;
    text-align: center;
    position: relative;
    overflow: hidden;
  }}
  .header::before {{
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse at 50% 0%, rgba(201,168,76,0.12) 0%, transparent 70%);
  }}
  .header h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    color: var(--gold-light);
    letter-spacing: -0.5px;
    position: relative;
  }}
  .header .subtitle {{
    color: var(--text-muted);
    margin-top: 0.5rem;
    font-size: 1rem;
    position: relative;
  }}
  .header .meta {{
    display: flex;
    gap: 2rem;
    justify-content: center;
    margin-top: 1.5rem;
    flex-wrap: wrap;
    position: relative;
  }}
  .meta-item {{
    background: rgba(201,168,76,0.08);
    border: 1px solid rgba(201,168,76,0.2);
    border-radius: 6px;
    padding: 0.4rem 1rem;
    font-size: 0.82rem;
    color: var(--gold-light);
  }}
  .container {{ max-width: 1400px; margin: 0 auto; padding: 2rem; }}

  /* KPI Bar */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1rem;
    margin-bottom: 2.5rem;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 1.25rem 1rem;
    text-align: center;
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute; top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--gold-dark), var(--gold));
  }}
  .kpi-value {{
    font-size: 1.9rem;
    font-weight: 700;
    color: var(--gold-light);
    letter-spacing: -1px;
  }}
  .kpi-label {{
    font-size: 0.75rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 0.25rem;
  }}
  .kpi-desc {{
    font-size: 0.72rem;
    color: var(--text-muted);
    margin-top: 0.4rem;
    opacity: 0.7;
  }}
  .kpi-card.negative .kpi-value {{ color: var(--red); }}

  /* Sections */
  .section {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1.75rem;
    margin-bottom: 2rem;
  }}
  .section-header {{
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--border);
  }}
  .section-number {{
    background: linear-gradient(135deg, var(--gold-dark), var(--gold));
    color: #0F0F14;
    width: 28px; height: 28px;
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.8rem;
    font-weight: 700;
    flex-shrink: 0;
  }}
  .section h2 {{
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text);
  }}
  .section .objective {{
    font-size: 0.82rem;
    color: var(--text-muted);
    margin-bottom: 1.25rem;
    font-style: italic;
    padding: 0.6rem 1rem;
    background: rgba(255,255,255,0.03);
    border-left: 3px solid var(--gold-dark);
    border-radius: 0 4px 4px 0;
  }}

  /* Charts */
  .chart-container {{
    position: relative;
    background: var(--surface2);
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
  }}
  .chart-title {{
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--gold-light);
    margin-bottom: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }}

  /* Two-col layout */
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
  }}
  .three-col {{
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
  }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
  }}
  th {{
    background: rgba(201,168,76,0.1);
    color: var(--gold-light);
    padding: 0.6rem 0.75rem;
    text-align: left;
    font-weight: 600;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }}
  td {{
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid rgba(255,255,255,0.04);
    color: var(--text);
  }}
  tr:hover td {{ background: rgba(255,255,255,0.02); }}

  /* Insights box */
  .insight-box {{
    background: rgba(201,168,76,0.06);
    border: 1px solid rgba(201,168,76,0.2);
    border-radius: 8px;
    padding: 1rem 1.25rem;
    margin-top: 1rem;
    font-size: 0.87rem;
  }}
  .insight-box h4 {{
    color: var(--gold-light);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.5rem;
  }}
  .insight-box ul {{
    list-style: none;
    padding: 0;
  }}
  .insight-box ul li::before {{
    content: '▸ ';
    color: var(--gold);
  }}
  .insight-box ul li {{ margin-bottom: 0.3rem; color: var(--text-muted); }}

  /* Regime legend */
  .regime-legend {{
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
    margin-top: 0.75rem;
    font-size: 0.8rem;
  }}
  .regime-item {{
    display: flex;
    align-items: center;
    gap: 0.4rem;
    color: var(--text-muted);
  }}
  .regime-dot {{
    width: 12px; height: 12px;
    border-radius: 2px;
  }}

  /* Footer */
  .footer {{
    text-align: center;
    padding: 2rem;
    color: var(--text-muted);
    font-size: 0.78rem;
    border-top: 1px solid var(--border);
    margin-top: 2rem;
  }}

  /* Badges */
  .badge {{
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.72rem;
    font-weight: 600;
  }}
  .badge-up {{ background: rgba(76,175,125,0.15); color: var(--green); }}
  .badge-down {{ background: rgba(224,85,85,0.15); color: var(--red); }}
  .badge-neutral {{ background: rgba(74,144,217,0.15); color: var(--blue); }}

  /* Heatmap */
  .heatmap-table td {{
    text-align: center;
    font-size: 0.72rem;
    min-width: 44px;
    padding: 0.3rem 0.2rem;
  }}
  .heatmap-table th {{
    text-align: center;
    min-width: 44px;
  }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
    .three-col {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<div class="header">
  <h1>Gold Price Dynamics</h1>
  <div class="subtitle">Comprehensive Trend &amp; Volatility Analysis — 2000 to 2026</div>
  <div class="meta">
    <span class="meta-item">Dataset: 6,399 Trading Days</span>
    <span class="meta-item">Period: Aug 2000 – Mar 2026</span>
    <span class="meta-item">Audience: Financial Analysts</span>
    <span class="meta-item">Asset: Gold (USD)</span>
    <span class="meta-item">Generated: April 2026</span>
  </div>
</div>

<div class="container">

  <!-- KPI Bar -->
  <div style="margin: 2rem 0 0.5rem; font-size:0.75rem; text-transform:uppercase; letter-spacing:1px; color:var(--text-muted);">Key Performance Indicators — Full Period</div>
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-value">+12.38%</div>
      <div class="kpi-label">Annualized Return (CAGR)</div>
      <div class="kpi-desc">Compound annual growth rate<br/>over ~25.5 years</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">17.69%</div>
      <div class="kpi-label">Annualized Volatility</div>
      <div class="kpi-desc">σ of daily log returns × √252</div>
    </div>
    <div class="kpi-card negative">
      <div class="kpi-value">-44.36%</div>
      <div class="kpi-label">Maximum Drawdown</div>
      <div class="kpi-desc">Peak $1,896 (Sep 2011)<br/>trough $1,049 (Dec 2015)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">4,766</div>
      <div class="kpi-label">Avg Daily Volume</div>
      <div class="kpi-desc">Contracts/day (2004–2026)<br/>excludes unreliable early data</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">0.70</div>
      <div class="kpi-label">Sharpe-Like Ratio</div>
      <div class="kpi-desc">CAGR ÷ Ann. Vol<br/>(zero risk-free rate assumed)</div>
    </div>
  </div>

  <!-- SECTION 1: Market Overview -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">1</div>
      <h2>Market Overview &amp; Long-Term Price Trend</h2>
    </div>
    <div class="objective">Summarize the overall trajectory of gold prices from 2000 to present, highlighting major bull and bear phases, all-time highs, and key inflection points.</div>

    <div class="chart-container">
      <div class="chart-title">Gold Closing Price (USD) — Daily, Aug 2000 – Mar 2026</div>
      <canvas id="priceChart" height="90"></canvas>
    </div>

    <div class="two-col" style="margin-top:1rem;">
      <div class="chart-container">
        <div class="chart-title">Annual Returns (%)</div>
        <canvas id="annualRetChart" height="160"></canvas>
      </div>
      <div>
        <table>
          <thead><tr><th>Phase</th><th>Period</th><th>Start</th><th>End</th><th>Return</th></tr></thead>
          <tbody>
            <tr><td>Secular Bull</td><td>2001–2011</td><td>$255</td><td>$1,896</td><td><span class="badge badge-up">+643%</span></td></tr>
            <tr><td>Bear Market</td><td>2011–2015</td><td>$1,896</td><td>$1,049</td><td><span class="badge badge-down">-44.7%</span></td></tr>
            <tr><td>Consolidation</td><td>2015–2018</td><td>$1,049</td><td>$1,178</td><td><span class="badge badge-neutral">+12.3%</span></td></tr>
            <tr><td>Recovery</td><td>2019–2020</td><td>$1,281</td><td>$1,975</td><td><span class="badge badge-up">+54.2%</span></td></tr>
            <tr><td>Consolidation II</td><td>2021–2023</td><td>$1,945</td><td>$2,062</td><td><span class="badge badge-neutral">+6.0%</span></td></tr>
            <tr><td>New Bull Run</td><td>2024–2026</td><td>$2,064</td><td>$5,377</td><td><span class="badge badge-up">+160%</span></td></tr>
          </tbody>
        </table>
        <div class="insight-box" style="margin-top:1rem;">
          <h4>Key Inflection Points</h4>
          <ul>
            <li><strong>Sep 2011:</strong> First cycle peak at $1,896 — GFC aftermath, USD weakness</li>
            <li><strong>Dec 2015:</strong> Trough at $1,049 — Fed tightening cycle, USD strength</li>
            <li><strong>Aug 2020:</strong> COVID-era ATH at ~$2,075 — unprecedented QE</li>
            <li><strong>2024–2026:</strong> New structural bull; ATH $5,377 (Mar 2026)</li>
          </ul>
        </div>
      </div>
    </div>
  </div>

  <!-- SECTION 2: Volatility -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">2</div>
      <h2>Volatility Analysis &amp; Regime Detection</h2>
    </div>
    <div class="objective">Analyze rolling volatility measures, identify periods of volatility clustering, and characterize distinct market regimes (low-vol, high-vol, crisis).</div>

    <div class="chart-container">
      <div class="chart-title">60-Day Rolling Annualized Volatility with Regime Bands</div>
      <canvas id="volChart" height="80"></canvas>
    </div>
    <div class="regime-legend">
      <div class="regime-item"><div class="regime-dot" style="background:rgba(76,175,125,0.6)"></div>Low-Vol Regime (&lt;13.5%)</div>
      <div class="regime-item"><div class="regime-dot" style="background:rgba(74,144,217,0.5)"></div>Mid-Vol Regime (13.5%–17.3%)</div>
      <div class="regime-item"><div class="regime-dot" style="background:rgba(224,85,85,0.6)"></div>High-Vol / Crisis (&gt;17.3%)</div>
    </div>

    <div class="two-col" style="margin-top:1rem;">
      <div class="chart-container">
        <div class="chart-title">Peak Volatility Episodes</div>
        <table>
          <thead><tr><th>Episode</th><th>Period</th><th>Peak Vol</th><th>Trigger</th></tr></thead>
          <tbody>
            <tr><td>GFC Spike</td><td>Sep–Nov 2008</td><td>~45%</td><td>Lehman collapse, credit crisis</td></tr>
            <tr><td>European Debt Crisis</td><td>Sep–Oct 2011</td><td>~38%</td><td>Eurozone sovereign stress</td></tr>
            <tr><td>Gold Bear Break</td><td>Apr 2013</td><td>~32%</td><td>Abrupt 13% drop in 2 days</td></tr>
            <tr><td>COVID Crash</td><td>Mar 2020</td><td>~35%</td><td>Pandemic liquidity seizure</td></tr>
            <tr><td>2022 Ukraine War</td><td>Mar 2022</td><td>~25%</td><td>Geopolitical shock, commodities</td></tr>
          </tbody>
        </table>
      </div>
      <div class="chart-container">
        <div class="chart-title">Drawdown from Running Peak</div>
        <canvas id="drawdownChart" height="140"></canvas>
      </div>
    </div>

    <div class="insight-box">
      <h4>Regime Characterization</h4>
      <ul>
        <li><strong>Low-vol regime (&lt;13.5% ann. vol):</strong> Typical of trending bull markets — 2002–2004, 2005–2007, 2016–2017, 2022–2023. Favorable risk-adjusted entry windows.</li>
        <li><strong>Mid-vol regime (13.5%–17.3%):</strong> Transition state. Common during post-crisis normalization and late-cycle consolidation phases.</li>
        <li><strong>High-vol/crisis (&gt;17.3%):</strong> GFC (2008), Euro Debt Crisis (2011), COVID (2020). Volatility clustering is pronounced — once elevated, regimes persist 6–18 months.</li>
        <li><strong>Max Drawdown of 44.36%</strong> materializes across a 4-year bear market (2011–2015), not a single crash — a critical risk-management consideration for long-only strategies.</li>
      </ul>
    </div>
  </div>

  <!-- SECTION 3: Seasonal -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">3</div>
      <h2>Seasonal &amp; Calendar-Based Patterns</h2>
    </div>
    <div class="objective">Examine whether gold exhibits recurring monthly or day-of-week patterns in returns, and quantify the strength of any seasonal effects.</div>

    <div class="two-col">
      <div class="chart-container">
        <div class="chart-title">Average Monthly Return (%) with t-Statistics</div>
        <canvas id="seasonalChart" height="160"></canvas>
      </div>
      <div>
        <table>
          <thead>
            <tr><th>Month</th><th>Avg Return</th><th>Std Dev</th><th>t-Stat</th><th>Signal</th></tr>
          </thead>
          <tbody id="monthTable"></tbody>
