  // Header
  let thead = '<thead><tr><th style="text-align:left;background:transparent;">Year</th>';
  months.forEach(m => thead += `<th>${{m}}</th>`);
  thead += '</tr></thead>';
  table.innerHTML = thead;

  const tbody = document.createElement('tbody');

  function getColor(val) {{
    if (val === null || val === undefined) return 'rgba(255,255,255,0.02)';
    if (val > 8) return 'rgba(76,175,125,0.9)';
    if (val > 4) return 'rgba(76,175,125,0.6)';
    if (val > 2) return 'rgba(76,175,125,0.35)';
    if (val > 0) return 'rgba(76,175,125,0.18)';
    if (val > -2) return 'rgba(224,85,85,0.18)';
    if (val > -4) return 'rgba(224,85,85,0.35)';
    if (val > -8) return 'rgba(224,85,85,0.6)';
    return 'rgba(224,85,85,0.9)';
  }}

  monthlyHeatmap.forEach(row => {{
    const tr = document.createElement('tr');
    let html = `<td style="color:var(--text-muted);font-weight:500">${{row.year}}</td>`;
    for (let m = 1; m <= 12; m++) {{
      const val = row[String(m)];
      const bg = getColor(val);
      const display = val !== null ? (val > 0 ? '+' : '') + val.toFixed(1) : '—';
      const textColor = val === null ? '#444' : Math.abs(val) > 4 ? '#fff' : 'var(--text)';
      html += `<td style="background:${{bg}};color:${{textColor}};border-radius:2px;">${{display}}</td>`;
    }}
    tr.innerHTML = html;
    tbody.appendChild(tr);
  }});

  table.appendChild(tbody);
}})();

// ============================================================
// 7. RETURN DISTRIBUTION HISTOGRAM
// ============================================================
(function() {{
  const centers = histCenters.map(v => (v * 100).toFixed(2));
  const counts = histCounts;

  // Compute normal curve overlay
  const mean = 0.047;
  const std = 1.114;
  const total = counts.reduce((a,b) => a+b, 0);
  const binWidth = (histCenters[1] - histCenters[0]) * 100;
  const normalCurve = histCenters.map(x => {{
    const xPct = x * 100;
    return total * binWidth * (1/(std * Math.sqrt(2*Math.PI))) * Math.exp(-0.5*((xPct-mean)/std)**2);
  }});

  new Chart(document.getElementById('histChart'), {{
    type: 'bar',
    data: {{
      labels: centers,
      datasets: [
        {{
          label: 'Observed Frequency',
          data: counts,
          backgroundColor: centers.map(v => {{
            const val = parseFloat(v);
            if (val < -3.1) return 'rgba(224,85,85,0.85)';
            if (val < -1.76) return 'rgba(224,85,85,0.5)';
            if (val > 0) return 'rgba(201,168,76,0.65)';
            return 'rgba(74,144,217,0.5)';
          }}),
          borderWidth: 0,
          categoryPercentage: 1.0,
          barPercentage: 1.0,
        }},
        {{
          label: 'Normal Distribution',
          data: normalCurve,
          type: 'line',
          borderColor: 'rgba(155,107,219,0.8)',
          borderWidth: 2,
          pointRadius: 0,
          fill: false,
          tension: 0.4,
        }}
