  table.innerHTML = thead;

  const tbody = document.createElement('tbody');

  function getColor(val) {{
    if (val === null || val === undefined) return 'rgba(255,255,255,0.02)';
    if (val > 8) return 'rgba(76,175,125,0.9)';
    if (val > 4) return 'rgba(76,175,125,0.6)';
    if (val > 2) return 'rgba(76,175,125,0.35)';
    if (val > 0) return 'rgba(76,175,125,0.18)';
    if (val > -2) return 'rgba(224,85,85,0.18)';
    if (val > -4) return 'rgba(224,85,85,0.35)';
    if (val > -8) return 'rgba(224,85,85,0.6)';
    return 'rgba(224,85,85,0.9)';
  }}

  monthlyHeatmap.forEach(row => {{
    const tr = document.createElement('tr');
