(function() {{
  const centers = histCenters.map(v => (v * 100).toFixed(2));
  const counts = histCounts;

  // Compute normal curve overlay
  const mean = 0.047;
  const std = 1.114;
  const total = counts.reduce((a,b) => a+b, 0);
  const binWidth = (histCenters[1] - histCenters[0]) * 100;
  const normalCurve = histCenters.map(x => {{
    const xPct = x * 100;
    return total * binWidth * (1/(std * Math.sqrt(2*Math.PI))) * Math.exp(-0.5*((xPct-mean)/std)**2);
  }});

  new Chart(document.getElementById('histChart'), {{
    type: 'bar',
    data: {{
      labels: centers,
      datasets: [
        {{
          label: 'Observed Frequency',
          data: counts,
          backgroundColor: centers.map(v => {{
